using System.Net;

namespace HabitsTracker.Identity.Adapters.Storage.Records;

/// <summary>A row of <c>identity.code_requests</c>; <see cref="EfCodeRequests"/> writes it from a <c>CodeRequest</c>.</summary>
public sealed class CodeRequestRecord
{
    // Generated by the database (identity column).
    public long Id { get; set; }

    public required string Email { get; set; }

    // Npgsql 10 maps IPNetwork to cidr; its NpgsqlCidr is obsolete.
    public required IPNetwork IpPrefix { get; set; }

    public required DateTimeOffset RequestedAt { get; set; }
}
